def handle(app, svc):
    resp = svc.apply(app)
    result = resp.get("result", resp)
    outcome = result.get("outcome", result.get("decision"))
    limit = result.get("credit_limit", result.get("limit", 0)) or 0

    # Network referral rule: self_employed with requested_limit > 6000
    # must go to manual review unless it's a decline.
    if (app.get("employment") == "self_employed"
            and app.get("requested_limit", 0) > 6000
            and outcome != "declined"):
        return {"action": "queue_review", "limit": 0}

    if outcome == "approved":
        return {"action": "issue", "limit": limit}
    if outcome == "declined":
        return {"action": "decline", "limit": 0}
    # manual_review
    return {"action": "queue_review", "limit": 0}
